Definition cntp (p : Z -> bool) (l : list Z) : Z := Z.of_nat (length (List.filter p l)).
Definition is_hit (e : Z) : bool := e =? 1.
(* [comment removed for export] *)
Definition prefix_ij (rows : list (list Z)) (i j : Z) : list Z :=
  concat (firstn (Z.to_nat i) rows) ++ firstn (Z.to_nat j) (nth (Z.to_nat i) rows []).

